-- ============================================================
-- INSTALADOR COMPLETO - Perfumeria Fina Peru
-- Pegar TODO este archivo en Supabase > SQL Editor > Run.
-- Incluye: 202 productos, datos de tienda, plantillas, calendario,
-- tabla de mensajes del bot y seguridad RLS.
-- Si el editor corta el pegado, usa los archivos 01a..01d, 02 y 03.
-- ============================================================

-- Catalogo Perfumeria Fina Peru: 202 productos
-- Pegar en Supabase > SQL Editor > Run. Es idempotente (se puede repetir).
begin;

create unique index if not exists productos_codigo_key on public.productos (codigo);

on conflict (id) do update set
  codigo = excluded.codigo,
  nombre = excluded.nombre,
  casa_inspirada = excluded.casa_inspirada,
  categoria = excluded.categoria,
  genero = excluded.genero,
  familia_olfativa = excluded.familia_olfativa,
  grupo_familia = excluded.grupo_familia,
  intensidad = excluded.intensidad,
  notas = excluded.notas,
  ocasiones = excluded.ocasiones,
  descripcion = excluded.descripcion,
  etiqueta = excluded.etiqueta,
  destacado = excluded.destacado,
  precio_50ml = excluded.precio_50ml,
  precio_100ml = excluded.precio_100ml,
  imagen_ruta = excluded.imagen_ruta,
  url_producto = excluded.url_producto,
  activo = excluded.activo;

commit;


-- ============================================================
-- Perfumeria Fina Peru - Datos iniciales y esquema complementario
-- Pegar en Supabase > SQL Editor > Run. Es idempotente.
-- ============================================================

begin;

-- 1) Datos de la tienda (una sola fila) ---------------------
select
  'Perfumería Fina Perú',
  'https://perfumeriafinaperu.com/assets/img/logo.png',
  '{"principal":"#E0B85A","fondo":"#07080C","texto":"#E8ECF4"}',
  'Cercano, amable y respetuoso, en español peruano neutro. Sin presión. Trata de "tú". Mensajes cortos, máximo 2 emojis.',
  'Yape, OY! y efectivo',
  'https://perfumeriafinaperu.com',
  '51910418951',
  'Lunes a sábado, de 9:00 a 20:00',
  'A todo el Perú desde Lima. Recojo en 7 estaciones: VMT sin costo, las demás S/ 5.'
where not exists (select 1 from public.configuracion_tienda);

-- 2) Plantillas base -----------------------------------------
select v.nombre, v.tipo, v.texto_base
from (values
  ('Promo 2 x 50 ml + 20 ml de regalo', 'promo',
   'Hola {nombre} 👋 En Perfumería Fina Perú tenemos una promo especial: 2 perfumes de 50 ml + 1 de 20 ml de regalo. Son fragancias equivalentes inspiradas en marcas conocidas, con 50% de esencia. ¿Te paso las disponibles? 🎁'),
  ('Promo 2 x 100 ml + 30 ml de regalo', 'promo',
   'Hola {nombre} ✨ Por esta semana: 2 perfumes de 100 ml + 1 de 30 ml de regalo. Son equivalentes de alta calidad, con 50% de esencia. ¿Quieres que te muestre las opciones? 🎁'),
  ('Combo 100 + 50 + 20 ml', 'promo',
   'Hola {nombre} 👋 Tenemos un combo ideal para regalar: 1 perfume de 100 ml + 1 de 50 ml + 1 de 20 ml de regalo. Fragancias equivalentes inspiradas en marcas conocidas. ¿Te reservo uno? 🎁'),
  ('Cumpleaños', 'cumpleaños',
   '¡Feliz cumpleaños, {nombre}! 🎉 En Perfumería Fina Perú queremos celebrarlo contigo con un detalle especial. Escríbenos y te ayudamos a elegir tu próxima fragancia.'),
  ('Recompra a los 2 meses', 'recompra',
   'Hola {nombre} 👋 Ya pasaron unas semanas desde tu última compra. ¿Quieres renovar tu fragancia o probar una nueva? Tenemos 50 ml desde S/ 58 y 100 ml desde S/ 82. Te ayudo a elegir.'),
  ('Novedad de la semana', 'novedad',
   'Hola {nombre} ✨ Llegaron nuevas fragancias a Perfumería Fina Perú. Son equivalentes de alta calidad, con 50% de esencia y en nuestro propio envase. ¿Te muestro las novedades de esta semana?'),
  ('Fiestas Patrias', 'festividad',
   'Hola {nombre} 🇵🇪 En Perfumería Fina Perú celebramos Fiestas Patrias con una promo especial. Fragancias equivalentes de 50 ml desde S/ 58 y 100 ml desde S/ 82. ¿Te reservo la tuya?'),
  ('Día de la Madre', 'festividad',
   'Hola {nombre} 🌸 Se acerca el Día de la Madre. En Perfumería Fina Perú tenemos fragancias equivalentes de alta calidad para sorprenderla. ¿Te ayudo a elegir la ideal?')
) as v(nombre, tipo, texto_base)
where not exists (select 1 from public.plantillas p where p.nombre = v.nombre);

-- 3) Mensajes del bot de WhatsApp ----------------------------
create table if not exists public.mensajes (
  id bigint generated by default as identity primary key,
  cliente_id text,
  telefono text not null,
  direccion text not null check (direccion in ('entrante', 'saliente')),
  texto text not null,
  origen text not null default 'bot',
  estado text not null default 'ok',
  creado_en timestamptz not null default now()
);

create index if not exists mensajes_telefono_idx on public.mensajes (telefono, creado_en desc);
create index if not exists mensajes_cliente_idx on public.mensajes (cliente_id);

-- 4) Ayudas para el calendario -------------------------------
-- fecha_programada ya existe. Aseguramos el índice para el calendario.
alter table public.campanas add column if not exists numero_emisor text;
create index if not exists campanas_fecha_programada_idx on public.campanas (fecha_programada);
create index if not exists clientes_cumpleanos_idx on public.clientes (fecha_cumpleanos);
create unique index if not exists clientes_telefono_key on public.clientes (telefono);

commit;

-- ============================================================
-- Perfumeria Fina Peru - Seguridad (RLS)
-- Pegar en Supabase > SQL Editor > Run.
--
-- IMPORTANTE: este script elimina las politicas actuales de estas
-- tablas y deja solo acceso para usuarios con sesion iniciada.
-- El panel usa Supabase Auth, asi que el dueno seguira entrando normal.
-- La clave publishable sola (sin login) ya no podra leer ni escribir.
-- ============================================================

begin;

alter table public.clientes            enable row level security;
alter table public.productos           enable row level security;
alter table public.plantillas          enable row level security;
alter table public.campanas            enable row level security;
alter table public.envios              enable row level security;
alter table public.configuracion_tienda enable row level security;
alter table public.mensajes            enable row level security;

-- Quitar politicas anteriores de estas tablas
do $$
declare r record;
begin
  for r in
    select policyname, tablename
    from pg_policies
    where schemaname = 'public'
      and tablename in ('clientes','productos','plantillas','campanas','envios','configuracion_tienda','mensajes')
  loop
    execute format('drop policy if exists %I on public.%I', r.policyname, r.tablename);
  end loop;
end $$;

-- Acceso total solo para el dueno con sesion iniciada
create policy panel_clientes on public.clientes
  for all to authenticated using (true) with check (true);
create policy panel_productos on public.productos
  for all to authenticated using (true) with check (true);
create policy panel_plantillas on public.plantillas
  for all to authenticated using (true) with check (true);
create policy panel_campanas on public.campanas
  for all to authenticated using (true) with check (true);
create policy panel_envios on public.envios
  for all to authenticated using (true) with check (true);
create policy panel_configuracion on public.configuracion_tienda
  for all to authenticated using (true) with check (true);
create policy panel_mensajes on public.mensajes
  for all to authenticated using (true) with check (true);

-- Datos obligatorios y validaciones basicas
alter table public.clientes alter column telefono set not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'clientes_telefono_formato') then
    alter table public.clientes
      add constraint clientes_telefono_formato check (telefono ~ '^51[0-9]{9}$');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'envios_estado_valido') then
    alter table public.envios
      add constraint envios_estado_valido check (estado in ('pendiente','enviado','omitido','error'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'campanas_estado_valido') then
    alter table public.campanas
      add constraint campanas_estado_valido check (estado in ('borrador','aprobada','programada','enviada'));
  end if;
end $$;

commit;

-- Despues de ejecutar:
-- 1. Ve a Authentication > Sign In / Providers y desactiva "Allow new users to sign up".
-- 2. Crea el usuario del dueno en Authentication > Users (email + password).
-- 3. Nunca pongas la clave service_role en el navegador ni en Cloudflare Pages.